export class RequestBuildQueueMoveItemUpEvent extends CustomEvent<{ index: string }> {
	constructor(index: string) {
		super("request-build-queue-move-item-up", {
			bubbles: true,
			detail: { index },
		});
	}
}

export class RequestBuildQueueMoveItemLastEvent extends CustomEvent<{ index: string }> {
	constructor(index: string) {
		super("request-build-queue-move-item-last", {
			bubbles: true,
			detail: { index },
		});
	}
}

export class RequestBuildQueueCancelItemEvent extends CustomEvent<{ index: string }> {
	constructor(index: string) {
		super("request-build-queue-cancel-item", {
			bubbles: true,
			detail: { index },
		});
	}
}

declare global {
	interface WindowEventMap {
		"request-build-queue-move-item-up": RequestBuildQueueMoveItemUpEvent;
		"request-build-queue-cancel-item": RequestBuildQueueCancelItemEvent;
		"request-build-queue-move-item-last": RequestBuildQueueMoveItemLastEvent;
	}
}
